    ok = ok and got == 0
    # 反例：近似但不匹配的串不得被误数
    got = count_markers("<!-- pagination -->\n<!-- page -->")
    print(f"  [{'ok' if got == 0 else 'FAIL'}] 反例 近似串不得误数: {got} (期望 0)")
    ok = ok and got == 0
    # 全库扫描：空库 0 页是合法状态；命中能力由下方合成库夹具钉住
    rows = sweep()
    print(f"  [info] 全库扫描跑通 -> {len(rows)} 页自称无标记（空库 0 属合法）")
    # ---- 夹具：合成库正例（只对临时目录，绝不碰真库）----
    import tempfile, shutil
