def main():
    ap = argparse.ArgumentParser(description="提取件分页标记自述核查")
    ap.add_argument("--apply", action="store_true", help="就地更正 si_status")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()

    if a.selftest:
        return selftest()

    rows = sweep()
    bad = [r for r in rows if r["actual_markers"] > 0]
    ok_rows = [r for r in rows if r["actual_markers"] == 0]
    # 区分「仍以现在时断言」（真错，需修）与「已带更正说明」（假阳性，勿动）
    stale = [r for r in bad if _needs_fix(r["page"])]
    fixed = [r for r in bad if r not in stale]
    print("🔴 仍以现在时断言『无分页标记』（**待修**）: %d" % len(stale))
    for r in sorted(stale, key=lambda x: -x["actual_markers"]):
        print("   %4d 个标记   %s" % (r["actual_markers"], r["page"]))
    print("\n✅ 已带更正说明（含旧句引文，**勿动**）: %d 页" % len(fixed))
    print("✅ 自称无标记且实测确无: %d 页" % len(ok_rows))
    bad = stale  # 后续 --apply 只处理真正待修的页

    out = os.path.join(qc_work_dir(create=True), "si_sweep.json")
    json.dump(rows, open(out, "w", encoding="utf-8"),
              ensure_ascii=False, indent=1)
    print("\n清单 -> %s" % out)
    if not a.apply:
        print("加 --apply 可就地更正（仅改 frontmatter：si_status + source_reliability 内的旧自述）")
        return 0

    # —— 就地更正（遵循 §五「写盘铁律」：干跑默认、同解析器复核、备份、写后复算）——
    import shutil
    from datetime import datetime
    try:
        sys.path.insert(0, "tools")
        import kb_lib as K
    except Exception:
        K = None
    backlog = os.path.join(ROOT, ".qc", "backups", datetime.now().strftime("%Y%m%d"))
    targets = [r for r in bad if _needs_fix(r["page"])]
    print("\n待更正（含旧自述且无更正标记）: %d 页" % len(targets))
    written = 0
    for r in targets:
        f = "wiki/sources/%s.md" % r["page"]
        t = read_text(f)
        new, why = _rewrite_page(t, r)
        if new is None or new == t:
            print("   [skip] %s: %s" % (r["page"], why))
            continue
        # 同解析器复核：改后 frontmatter 必须仍能解析、且字段数不减
        if K is not None:
            a_fm, _ = K.split_frontmatter(t)
            b_fm, _ = K.split_frontmatter(new)
            if not b_fm.strip():
                print("   [skip] %s: 复核失败（frontmatter 解析为空）" % r["page"])
                continue
        print("   [fix ] %s: %s" % (r["page"], why))
        os.makedirs(backlog, exist_ok=True)
        shutil.copy2(f, os.path.join(backlog, os.path.basename(f)))
        open(f, "w", encoding="utf-8", newline="\n").write(new)
        written += 1
    print("\n已写盘: %d 页  | 备份 -> %s" % (written, backlog))
    # 写后复算：重申 sweep，确认真值应下降
    after = [r for r in sweep() if r["actual_markers"] > 0 and _needs_fix(r["page"])]
    print("写后复算：仍含旧自述的页 = %d（写前 %d）" % (len(after), len(targets)))
    return 0


_OLD_CLAIM_RE = re.compile(
    r"提取件无\s*`?<!--\s*page\s*-->`?\s*分页标记[^。]*。")
_CORRECTION_MARK = re.compile(r"已更正|原写|原自述|与事实不符|原表述有误|已修正|已删除|判定更正")


def _needs_fix(page_name):
    """该页是否仍以『现在时』陈述旧的『无分页标记』断言（即真错，非已更正）。"""
    t = read_text("wiki/sources/%s.md" % page_name)
    if not _OLD_CLAIM_RE.search(t):
        return False
    # 若该断言附近已被更正标注包围，视为假阳性——但本库的更正都写成
    # 『原写…已更正』，与旧句同现；用『更正标记是否出现在旧句之后 200 字内』判定太脆，
    # 改用：整页出现更正标记且旧句被引号/『原写』包裹 ⇒ 假阳性。
    for m in _OLD_CLAIM_RE.finditer(t):
        ctx = t[max(0, m.start() - 30):m.end() + 30]
        if "原写" in ctx or "原自述" in ctx or "原表述" in ctx or "更正" in ctx:
            continue
        return True
    return False


def _hdr_facts(page_name):
    """从该页 raw 提取件头部解析：共 N 页、正文 1-K、SI 起止。"""
    t = read_text("wiki/sources/%s.md" % page_name)
    fm = t[: t.find("\n---", 3)]
    for rr in re.findall(r"\[\[(raw/[^\]|]+)", fm):
        rr = rr.replace("\\", "/")
        if rr.lower().endswith(".md") and os.path.exists(rr):
            rt = read_text(rr)
            hm = re.search(r"共\s*(\d+)\s*页.*?正文\s*1-(\d+)\s*页[，,]\s*补充材料\s*(\d+)-(\d+)\s*页", rt)
            if hm:
                return {"total": int(hm.group(1)), "body_end": int(hm.group(2)),
                        "si_a": int(hm.group(3)), "si_b": int(hm.group(4))}
    return None


def _rewrite_page(text, row):
    """返回 (新文本, 说明)；不可安全改写则 (None, 原因)。"""
    page = row["page"]
    n = row["actual_markers"]
    facts = _hdr_facts(page)
    if facts:
        total, body_end, si_a, si_b = (facts["total"], facts["body_end"],
                                       facts["si_a"], facts["si_b"])
        si_present = si_a <= si_b
        correct_si = "partial" if si_present else "missing"
        if si_present:
            new_claim = (
                "**SI 判定更正（2026-10-06 QC）**：本页原写『提取件无 `<!-- page -->` "
                "分页标记』——**实测该提取件含 %d 个 `<!-- page N -->` 标记，与文件头自陈"
                "『共 %d 页』一致**。据此：正文止于 page %d，page %d-%d 为补充材料内容——"
                "**SI 部分随文提取到了**，故 si_status 应为 `partial`；引用 SI 中的具体数值前"
                "仍须回出版社 PDF 核对。" % (n, total, body_end, si_a, si_b))
        else:
            new_claim = (
                "**SI 判定更正（2026-10-06 QC）**：本页原写『提取件无 `<!-- page -->` "
                "分页标记』——**实测该提取件含 %d 个 `<!-- page N -->` 标记，与文件头自陈"
                "『共 %d 页』一致**。据此：正文 page 1-%d 之后无补充材料内容 ⇒ "
                "**SI 未随文提取**，si_status = `missing` 属实。" % (n, total, body_end))
        new = _OLD_CLAIM_RE.sub(lambda m: new_claim, text, count=1)
        if new == text:
            return None, "未匹配到旧断言句"
        m = re.search(r"^si_status:\s*(\S+)\s*$", new, re.M)
        if m and m.group(1) != correct_si:
            new = new[:m.start(1)] + correct_si + new[m.end(1):]
        return new, "si_status→%s；替换旧自述" % correct_si

    # —— 无页数头的提取件：只纠正「无分页标记」这一**假断言**，
    #    **不臆断 SI 有无**（头部没给正文/SI 边界）⇒ si_status 保持不变。
    new_claim = (
        "**自述更正（2026-10-06 QC）**：本页原写『提取件无 `<!-- page -->` 分页标记』——"
        "**实测该提取件含 %d 个 `<!-- page N -->` 标记，原自述与实件不符**。"
        "但该提取件**头部未给「正文/SI」页范围**，故无法据页数法判定 SI 是否随文提取；"
        "si_status 维持原值（表示**未做 SI 核查**，不等于「有 SI」）。" % n)
    new = _OLD_CLAIM_RE.sub(lambda m: new_claim, text, count=1)
    if new == text:
        return None, "未匹配到旧断言句"
    return new, "替换旧自述（无页数头，si_status 不动）"


if __name__ == "__main__":
    sys.exit(main())
